SELECT

FROM PERF_TARGET_PLAN


        AND kpi_scheme_id = #{kpiSchemeId}


        AND status = #{status}


        AND (
            plan_code LIKE CONCAT('%', #{keyword}, '%')
            OR plan_name LIKE CONCAT('%', #{keyword}, '%')
        )


ORDER BY plan_code ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM PERF_TARGET_PLAN


        AND kpi_scheme_id = #{kpiSchemeId}


        AND status = #{status}


        AND (
            plan_code LIKE CONCAT('%', #{keyword}, '%')
            OR plan_name LIKE CONCAT('%', #{keyword}, '%')
        )

